  const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };
  const jfmt = new Intl.DateTimeFormat("en-u-ca-persian-nu-latn", { year: "numeric", month: "numeric", day: "numeric" });
  function jparts(d) {
