      let seed = 7;
      const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
      for (let i = 0; i < Math.min(160, w / 6); i++) {
        const x = rnd() * w, y = rnd() * hh * 0.85, r = rnd() * 1.3 + 0.2;
        ctx.globalAlpha = 0.25 + rnd() * 0.7; ctx.fillStyle = "#fff";
